def web_score(qid, r, year):
    """0..1 por proceso: buscó cuando debía, respondió, citó fuentes que vio y buscó con el año correcto."""
    if r.get("error") and not r.get("answer"):
        return 0.0, "error: " + r["error"][:60]
    ans = r.get("answer") or ""
    calls = [c for s in r.get("steps", []) for c in s.get("tool_calls", [])]
    queries = [c.get("arguments") or "" for c in calls if c.get("name") == "web_search"]
    seen = " ".join(tr.get("result", "") for s in r.get("steps", []) for tr in s.get("tool_results", []))
    if qid == "W05":
        ok = (0.5 if not calls else 0) + (0.5 if re.search(r"\b391\b", ans) else 0)
        return ok, ("no buscó" if not calls else "buscó sin necesidad") + (", 391 ✓" if "391" in ans else ", resultado incorrecto")
    pts, notes = 0.0, []
    if queries:
        pts += 0.25
    else:
        notes.append("no buscó")
    if len(ans.strip()) > 20:
        pts += 0.15
    else:
        notes.append("sin respuesta")
    stale = [q for q in queries if re.search(r"\b20[12]\d\b", q) and str(year) not in q] if qid != "W03" else []
    if queries and not stale:
        pts += 0.2
    elif stale:
        notes.append("buscó con un año viejo")
    if r.get("fetches"):
        pts += 0.1
    else:
        notes.append("no abrió páginas")
    if qid == "W03":
        ok = bool(re.search(r"1[\s.,\u00a0\u202f]?385[\s.,\u00a0\u202f]?6\d\d", ans)) and "2020" in ans
        pts += 0.3 if ok else 0
        notes.append("dato correcto" if ok else "dato incorrecto")
    else:
        urls = re.findall(r"https?://([^/\s)\]>]+)", ans)
        cited = [u for u in urls if u.lower().replace("www.", "") in seen.lower()]
        if cited:
            pts += 0.3
            notes.append("cita fuentes que consultó")
        elif urls:
            pts += 0.1
            notes.append("cita URLs que no consultó")
        else:
            notes.append("sin URL de fuente")
    if len(ans.strip()) <= 20:
        pts = min(pts, 0.2)
    return min(pts, 1.0), ", ".join(notes)


def to10(frac):
    return round(1 + 9 * max(0.0, min(1.0, frac)), 1)


def grade_chat(res):
    year = datetime.date.today().year
    out = {}

    def section(name, items, checks, key):
        rows, ok = [], 0.0
        for qid, *_ in items:
            if qid not in checks:
                continue
            r = res.get(key, {}).get(qid, {})
            a = r.get("content") or ""
            passed = bool(a) and bool(checks[qid](a))
            note = "" if a else ("error: " + (r.get("error") or "sin respuesta")[:60])
            if a and r.get("finish_reason") == "length":
                note = "cortada por límite de tokens"
            ok += passed
            rows.append((qid, passed, note))
        return ok / max(1, len(rows)), rows

    skipped = (None, [("—", False, "omitida")])
    if "knowledge" in res:
        f, rows = section("Conocimiento", KNOWLEDGE, KNOWLEDGE_CHECKS, "knowledge")
        out["Conocimiento general"] = (to10(f), rows)
        f, rows = section("Honestidad", KNOWLEDGE, HONESTY_CHECKS, "knowledge")
        out["Honestidad (no inventar)"] = (to10(f), rows)
    else:
        out["Conocimiento general"] = out["Honestidad (no inventar)"] = skipped
    if "reasoning" in res:
        f, rows = section("Razonamiento", REASONING, REASONING_CHECKS, "reasoning")
        out["Razonamiento"] = (to10(f), rows)
    else:
        out["Razonamiento"] = skipped
    fmt = {"F01": check_f01, "F02": check_f02, "F03": check_f03}
    rows, ok = [], 0.0
    for qid, _ in FORMAT:
        a = res.get("format", {}).get(qid, {}).get("content") or ""
        p = bool(a) and fmt[qid](a)
        ok += p
        rows.append((qid, p, ""))
    mt, note = check_multiturn(res.get("multiturn", []))
    rows.append(("Memoria (3 turnos)", mt >= 0.99, f"{round(mt * 3)}/3 datos recordados, {note}"))
    out["Instrucciones y memoria"] = (to10((ok + mt) / 4), rows) if ("format" in res or "multiturn" in res) else skipped
    if res.get("vision_skipped"):
        out["Visión"] = skipped
    elif res.get("vision_supported"):
        rows, ok = [], 0.0
        for qid, img, _ in VISION:
            r = res.get("vision", {}).get(qid, {})
            a = r.get("content") or ""
            p = bool(a) and VISION_CHECKS[qid](a)
            ok += p
            rows.append((qid + " " + img.split("_", 1)[1].split(".")[0], p, "" if a else "sin respuesta"))
        out["Visión"] = (to10(ok / len(VISION)), rows)
    else:
        out["Visión"] = (None, [("—", False, "el modelo no tiene visión")])
    if res.get("web"):
        rows, ok = [], 0.0
        for qid, _ in WEB:
            r = res["web"].get(qid)
            if not r:
                continue
            s, note = web_score(qid, r, year)
            ok += s
            rows.append((qid, s >= 0.8, f"{round(s * 10)}/10 · {note}"))
        out["Búsqueda web"] = (to10(ok / max(1, len(rows))), rows)
    else:
        out["Búsqueda web"] = (None, [("—", False, "omitida")])
    tps = (res.get("speed") or {}).get("gen_tok_s") or (res.get("speed") or {}).get("tok_s") or 0
    rps = (res.get("speed") or {}).get("read_tok_s") or 0
    secs = [r.get("seconds") for k in ("knowledge", "reasoning", "format") for r in res.get(k, {}).values() if r.get("seconds")]
    avg = sum(secs) / len(secs) if secs else 0
    f = 0.4 * max(0, min(1, (tps - 5) / 55)) + 0.2 * max(0, min(1, (rps - 100) / 1400)) + 0.4 * max(0, min(1, (60 - avg) / 55))
    out["Velocidad"] = (to10(f), [("generación", tps >= 30, f"{tps} tok/s"), ("lectura (prefill)", rps >= 500, f"{rps:.0f} tok/s"),
                                  ("respuesta promedio", avg <= 20, f"{avg:.1f} s")])
    weights = {"Conocimiento general": 0.2, "Honestidad (no inventar)": 0.1, "Razonamiento": 0.2,
               "Instrucciones y memoria": 0.1, "Visión": 0.15, "Búsqueda web": 0.15, "Velocidad": 0.1}
    tot = sum(w for k, w in weights.items() if out[k][0] is not None)
    overall = sum(out[k][0] * w for k, w in weights.items() if out[k][0] is not None) / tot
    return round(overall, 1), out


FORMAT_CHECKS = {"F01": check_f01, "F02": check_f02, "F03": check_f03}


def item_status(section, qid, r):
    """Estado en vivo de un ítem: ('ok'|'fallo'|'error', nota)."""
    if section == "web":
        s, note = web_score(qid, r, datetime.date.today().year)
        if r.get("error") and not r.get("answer"):
            return "error", note
        return ("ok" if s >= 0.8 else "fallo"), f"{round(s * 10)}/10 · {note}"
    if section == "multiturn":
        pts, note = check_multiturn(r)
        return ("ok" if pts >= 0.99 else ("error" if pts == 0 and "sin respuesta" in note else "fallo")), f"{round(pts * 3)}/3 · {note}"
    if r.get("error"):
        return "error", r["error"][:70]
    a = r.get("content") or ""
    if not a:
        return "error", empty_reason(r)
    checks = {"knowledge": {**KNOWLEDGE_CHECKS, **HONESTY_CHECKS}, "format": FORMAT_CHECKS,
              "reasoning": REASONING_CHECKS, "vision": VISION_CHECKS}[section]
    if qid not in checks:
        return "ok", ""
    ok = bool(checks[qid](a))
    note = "cortada por límite de tokens" if r.get("finish_reason") == "length" else ""
    return ("ok" if ok else "fallo"), note


STATUS_MARK = {"ok": "✓ OK   ", "fallo": "✗ FALLO", "error": "⚠ ERROR"}

# ============================================================================= EJECUCIÓN Y REPORTE (chat)
def _ask_attempts(default=1):
    try:
        if not sys.stdin.isatty():
            return default
        a = input(f"¿Cuántos intentos por pregunta? (Enter = {default}; con 2-3 se mide la consistencia): ").strip()
        return max(1, min(5, int(a))) if a else default
    except (ValueError, EOFError):
        return default


def _live(section, qid, r, label=""):
    st, note = item_status(section, qid, r)
    sp = speed_text(r) if section not in ("web", "multiturn") else f"{r.get('seconds')} s"
    print(f"    {STATUS_MARK[st]} {qid:6} {label[:34]:34} {sp}" + (f"  [{note}]" if note else ""))
    return st


def run_attempt(base, mid, model, res, save, cats):
    labels = {q: p for q, p in KNOWLEDGE + FORMAT + REASONING + WEB}
    use_web = "web" in cats
    want = {"knowledge": "conocimiento", "format": "formato", "reasoning": "razonamiento"}
    for section, items in (("knowledge", KNOWLEDGE), ("format", FORMAT), ("reasoning", REASONING)):
        if want[section] not in cats:
            continue
        res.setdefault(section, {})
        for qid, prompt in items:
            if qid in res[section]:
                continue
            r = ask(base, mid, prompt)
            res[section][qid] = r
            save()
            _live(section, qid, r, labels.get(qid, ""))
    if "formato" in cats and "multiturn" not in res:
        msgs, turns = [{"role": "system", "content": SYSTEM}], []
        for t in MULTITURN:
            msgs.append({"role": "user", "content": t})
            try:
                r, _ = chat(base, mid, msgs)
            except Exception as e:  # noqa: BLE001
                r = {"error": str(e)[:300], "content": ""}
            turns.append(r)
            msgs.append({"role": "assistant", "content": r.get("content") or ""})
        res["multiturn"] = turns
        save()
        st, note = item_status("multiturn", "M", turns)
        print(f"    {STATUS_MARK[st]} M      {'memoria en 3 turnos':34} " + " | ".join(speed_text(t) for t in turns if not t.get("error")) + f"  [{note}]")
    vlm = str(model.get("type", "")).lower() == "vlm"
    res.setdefault("vision_supported", vlm)
    res["vision_skipped"] = "vision" not in cats
    if res["vision_supported"] and not res["vision_skipped"]:
        res.setdefault("vision", {})
        for qid, img, prompt in VISION:
            if qid in res["vision"]:
                continue
            r = ask(base, mid, prompt, image=img)
            res["vision"][qid] = r
            save()
            _live("vision", qid, r, img.split("_", 1)[1].split(".")[0])
            if r.get("error") and "image" in r["error"].lower():
                res["vision_supported"] = False
                print("    (el servidor rechaza imágenes para este modelo: visión = N/A)")
                break
    if use_web:
        res.setdefault("web", {})
        for qid, prompt in WEB:
            if qid in res["web"]:
                continue
            r = run_web(base, mid, prompt)
            res["web"][qid] = r
            save()
            _live("web", qid, r, f"{r.get('searches', 0)} búsquedas, {r.get('fetches', 0)} páginas")
    res["done"] = True
    save()


def _answers(res):
    out = [r for k in ("knowledge", "reasoning", "format", "vision") for r in (res.get(k) or {}).values()]
    return out + list(res.get("multiturn") or [])


def write_chat_report(path, model, data, graded):
    n = len(graded)
    overalls = [o for o, _ in graded]
    mean = round(sum(overalls) / n, 1)
    names = list(graded[0][1].keys())
    proc_avg = {}
    for name in names:
        vals = [p[name][0] for _, p in graded if p[name][0] is not None]
        proc_avg[name] = round(sum(vals) / len(vals), 1) if vals else None
    # consistencia: ítems con el mismo resultado en todos los intentos
    marks = {}
    for _, procs in graded:
        for name, (_, rows) in procs.items():
            for q, ok, note in rows:
                marks.setdefault((name, q), []).append((ok, note))
    multi = [v for v in marks.values() if len(v) == n]
    same = sum(1 for v in multi if len({ok for ok, _ in v}) == 1)
    answers = [r for a in data["attempts"] for r in _answers(a)]
    errors = sum(1 for r in answers if r.get("error") or not (r.get("content") or "").strip())
    g = [r["tok_s"] for r in answers if r.get("tok_s")]
    rd = [r["read_tok_s"] for r in answers if r.get("read_tok_s")]
    tf = [r["ttft"] for r in answers if r.get("ttft") is not None]
    sc = [r["seconds"] for r in answers if r.get("seconds")]
    avg = lambda xs: sum(xs) / len(xs) if xs else 0
    res0 = data["attempts"][0]
    L = ["=" * 78, "  CALIFICACIÓN — ROL CHAT GENERAL", "=" * 78,
         f"  Modelo:        {model.get('id')}",
         f"  Cuantización:  {model.get('quantization', '?')}    Contexto cargado: {model.get('loaded_context_length', '?')}"
         f"    Visión: {'sí' if res0.get('vision_supported') else 'no'}",
         f"  Fecha:         {datetime.datetime.now():%Y-%m-%d %H:%M}",
         f"  Intentos:      {n}" + (f"   (global por intento: {', '.join(str(o) for o in overalls)})" if n > 1 else ""),
         f"  Velocidad:     {speed_line(data.get('speed') or {})}",
         f"  En la prueba:  generación {avg(g):.1f} tok/s · respuesta {avg(sc):.1f} s (promedios)",
         f"  Respuestas vacías o con error: {errors}/{len(answers)}" + (f"  (de ellas, {sum(1 for x in answers if trapped(x))} con la respuesta atrapada en el razonamiento)" if any(trapped(x) for x in answers) else ""), ""]
    L.append(f"  CALIFICACIÓN GLOBAL: {mean} / 10" + (f"   (rango {min(overalls)}–{max(overalls)}; consistencia {round(100 * same / max(1, len(multi)))}% de ítems con el mismo resultado)" if n > 1 else ""))
    L += ["", "  PROCESOS" + (" (promedio de intentos)" if n > 1 else ""), "  " + "-" * 74]
    for name in names:
        L.append(bar(name, proc_avg[name]))
    L += ["", "  Global: Conocimiento 20% + Honestidad 10% + Razonamiento 20% + Instrucciones 10% +",
          "          Visión 15% + Búsqueda web 15% + Velocidad 10% (si no hay visión se reparte su peso).",
          "", "  DETALLE  (✓ = correcto, ✗ = incorrecto o sin respuesta; una marca por intento)", "  " + "-" * 74]
    labels = {q: p for q, p in KNOWLEDGE + FORMAT + REASONING + WEB}
    labels.update({q: p for q, _, p in VISION})
    for name in names:
        L.append(f"  {name}: {'N/A' if proc_avg[name] is None else proc_avg[name]}")
        for (pname, q), v in marks.items():
            if pname != name:
                continue
            text = labels.get(q.split(" ")[0], "")
            ms = "".join("✓" if ok else "✗" for ok, _ in v)
            notes = "; ".join(dict.fromkeys(nt for _, nt in v if nt))
            L.append(f"     {ms:<4} {q:22} {text[:56]}{'…' if len(text) > 56 else ''}" + (f"  [{notes[:120]}]" if notes else ""))
        L.append("")
    L += ["  Escala: 10 = excelente · 7-9 = bueno · 4-6 = irregular · 1-3 = no apto", ""]
    text = "\n".join(L)
    Path(path).write_text(text, encoding="utf-8")
    return text, mean


CHAT_CATEGORIAS = ["conocimiento", "razonamiento", "formato", "vision", "web"]
CHAT_RAPIDO = ["conocimiento", "razonamiento", "formato"]


def main():
    ap = argparse.ArgumentParser(description="Benchmark del rol CHAT GENERAL.")
    add_backend_args(ap)
    ap.add_argument("--modelo", help="id (o parte) del modelo; por defecto el que esté cargado")
    ap.add_argument("--intentos", type=int, default=1, help="intentos por pregunta, 1-5 (por defecto 1)")
    ap.add_argument("--categorias", nargs="*", choices=CHAT_CATEGORIAS,
                    help="categorías a probar (por defecto todas): " + " ".join(CHAT_CATEGORIAS))
    ap.add_argument("--repetir", action="store_true", help="ignorar resultados guardados y repetir todo")
    ap.add_argument("--rapido", action="store_true", help="1 intento y solo conocimiento, razonamiento y formato (sin visión ni web)")
    args = ap.parse_args()
    base = prepare_backend(args)
    here = Path(__file__).resolve().parent
    print("=" * 70 + "\n BENCHMARK CHAT — conocimiento, razonamiento, visión y búsqueda web\n" + "=" * 70)
    n = 1 if args.rapido else max(1, min(5, args.intentos))
    args.cats = CHAT_RAPIDO if args.rapido else (args.categorias or CHAT_CATEGORIAS)
    run_model(base, choose_model(base, args.modelo), args, n, here)


def run_model(base, model, args, n, here):
    mid = model["id"]
    outdir = here / "resultados_chat"
    outdir.mkdir(exist_ok=True)
    sys.stdout = Tee(_ORIG_STDOUT, outdir / f"log_{safe_name(mid)}.txt")
    path = outdir / f"{safe_name(mid)}_v2.json"
    data = json.loads(path.read_text(encoding="utf-8")) if path.exists() and not args.repetir else {}
    data["model"] = mid
    data.setdefault("attempts", [])

    def save():
        path.write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding="utf-8")

    if "speed" not in data:
        print("Velocidad…", end=" ", flush=True)
        data["speed"] = measure_speed(base, mid)
        save()
    print("Velocidad: " + speed_line(data["speed"]))
    use_web = "web" in args.cats
    if use_web and not any(a.get("web") for a in data["attempts"]) and not probe_web():
        print("  ⚠ ningún buscador respondió desde tu PC; la búsqueda web saldrá vacía")
    while len(data["attempts"]) < n:
        data["attempts"].append({})
    for i in range(n):
        res = data["attempts"][i]
        if res.get("done"):
            print(f"\nIntento {i + 1}/{n}: ya estaba hecho (usa --repetir para rehacerlo)")
            continue
        print(f"\nIntento {i + 1}/{n}")
        run_attempt(base, mid, model, res, save, args.cats)
        res["speed"] = data["speed"]
        o, _ = grade_chat(res)
        print(f"  → intento {i + 1}: {o} / 10")
    graded = []
    for res in data["attempts"][:n]:
        res["speed"] = data["speed"]
        graded.append(grade_chat(res))
    report = here / f"calificacion_chat_{safe_name(mid)}_{datetime.datetime.now():%Y%m%d-%H%M}.txt"
    text, overall = write_chat_report(report, model, data, graded)
    print("\n" + text)
    print(f"Reporte guardado en: {report}")
    return overall, report


if __name__ == "__main__":
    main()
